"use client";
import {
  RiBuilding2Line,
  RiEyeLine,
  RiFlashlightLine,
  RiGroupLine,
  RiUserAddLine,
  RiVipCrownLine,
} from "@remixicon/react";
import { useState } from "react";
import { cx } from "../../utils/cx";
import { formatNumber } from "./chart-card";
import type { FunnelChartRange, FunnelStage } from "./funnel-chart-card";
import {
  type ChartCommonProps,
  ChartFrame,
  ink,
  PeriodSelect,
  StatTiles,
  safeRatio,
  useChartRange,
} from "./pro-chart";
export type StageBar = FunnelStage;
export type StageBarsRange = FunnelChartRange;
export interface StageBarsCardProps extends ChartCommonProps {
  stages?: StageBar[];
  ranges?: StageBarsRange[];
  mono?: boolean;
  showIcons?: boolean;
  tiles?: boolean;
}
const ICONS = [
  RiEyeLine,
  RiUserAddLine,
  RiFlashlightLine,
  RiVipCrownLine,
  RiGroupLine,
  RiBuilding2Line,
];
export const STAGE_BARS: StageBar[] = [
  "Visits",
  "Sign-up",
  "Active",
  "Pro",
  "Team",
  "Enterprise",
].map((label, i) => {
  const Icon = ICONS[i]!;
  return {
    label,
    value: [1180, 790, 460, 250, 120, 40][i]!,
    icon: <Icon className="size-3.5 shrink-0 text-neutral-950" />,
  };
});
const RANGES: StageBarsRange[] = [
  { id: "7d", label: "Last 7 days", stages: STAGE_BARS, delta: 0.024 },
  {
    id: "30d",
    label: "Last 30 days",
    stages: STAGE_BARS.map((s, i) => ({
      ...s,
      value: [4820, 3260, 2010, 1160, 540, 180][i]!,
    })),
    delta: 0.061,
  },
  {
    id: "90d",
    label: "Last 90 days",
    stages: STAGE_BARS.map((s, i) => ({
      ...s,
      value: [13900, 9410, 5720, 3300, 1520, 510][i]!,
    })),
    delta: -0.012,
  },
];
export function StageBarsCard({
  stages,
  ranges: supplied,
  title = "Pipeline",
  mono = false,
  showIcons = true,
  tiles = true,
  ...props
}: StageBarsCardProps = {}) {
  const ranges = supplied ?? (stages ? undefined : RANGES),
    period = useChartRange(ranges, props.defaultRange, props.onRangeChange),
    data = period.current?.stages ?? stages ?? STAGE_BARS,
    [active, setActive] = useState<number | null>(null),
    format = props.format ?? formatNumber,
    first = data[0]?.value ?? 0,
    colors = data.map((s, i) =>
      mono ? "var(--color-text-tertiary)" : (s.color ?? ink(i)),
    );
  return (
    <ChartFrame
      title={active == null ? title : (data[active]?.label ?? title)}
      value={
        active == null
          ? (period.current?.headline ?? props.headline ?? first)
          : (data[active]?.value ?? 0)
      }
      format={format}
      delta={
        active == null ? (period.current?.delta ?? props.delta) : undefined
      }
      animateNumber
      pulseKey={`${period.id}:${active ?? "total"}`}
      className={cx("h-auto min-h-[329px]", props.className)}
      action={
        <PeriodSelect
          ranges={ranges}
          selected={period.id}
          onChange={(id) => {
            setActive(null);
            period.select(id);
          }}
          label={period.current?.label ?? props.range ?? "Last 7 days"}
        />
      }
      footer={
        tiles && (
          <StatTiles
            items={data.map((s, i) => ({
              label: s.label,
              value: format(s.value),
              color: colors[i],
              activeColor: mono
                ? "var(--color-text-tertiary)"
                : (s.color ?? ink(i, true)),
            }))}
            active={active}
            onHover={setActive}
            inactiveOpacity={0.5}
            focusable={false}
            className="grid grid-cols-3"
          />
        )
      }
    >
      <div
        className="grid min-h-0 w-full flex-1 content-center items-center gap-x-3 gap-y-3 py-2"
        style={{
          gridTemplateColumns: "auto minmax(0, 1fr) auto",
          gridTemplateRows: `repeat(${data.length}, auto)`,
        }}
      >
        {data.map((stage, i) => (
          <div
            className="contents"
            key={stage.label}
            onMouseEnter={() => setActive(i)}
            onMouseLeave={() => setActive(null)}
          >
            <span
              className="text-end text-body-regular whitespace-nowrap text-text-secondary transition-opacity duration-200 ease-out"
              style={{ opacity: active != null && active !== i ? 0.35 : 1 }}
            >
              {stage.label}
            </span>
            <div
              className="relative h-5 min-w-0 overflow-hidden rounded-full bg-chart-track transition-opacity duration-200 ease-out"
              style={{ opacity: active != null && active !== i ? 0.35 : 1 }}
            >
              <div
                className="absolute inset-y-0 start-0 rounded-full transition-[width,background-color] duration-500 ease-out"
                style={{
                  width: `${safeRatio(stage.value, first) * 100}%`,
                  backgroundColor:
                    active === i && !mono
                      ? (stage.color ?? ink(i, true))
                      : colors[i],
                }}
              />
              {showIcons && stage.icon && (
                <span className="pointer-events-none absolute inset-y-0 start-1 flex items-center text-neutral-950">
                  {stage.icon}
                </span>
              )}
            </div>
            <span
              className="flex items-baseline justify-end gap-1.5 whitespace-nowrap transition-opacity duration-200 ease-out"
              style={{ opacity: active != null && active !== i ? 0.35 : 1 }}
            >
              <span className="text-body-medium text-text-primary tabular-nums">
                {format(stage.value)}
              </span>
              <span className="text-caption-1-medium text-text-tertiary tabular-nums">
                {Math.round(safeRatio(stage.value, first) * 100)}%
              </span>
            </span>
          </div>
        ))}
      </div>
    </ChartFrame>
  );
}
